from .devices.signal_analyzer import SignalAnalyzer
from .exceptions import IncorrectAlias
from .facade import SignalAnalyzerFacade
from .frequency_units import FrequencyUnits


class signal_analyzer(object):
    """ Handles operations on configured signal analyzers """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, configured_signal_analyzer = aliasing_scope(name=__name__, lookup_arg='alias',
                                                                lookup_type=SignalAnalyzer)

    def __init__(self):
        self._facade = SignalAnalyzerFacade()

    def setup_signal_analyzer(self, model, ip, alias=None, **kwargs):
        """
        Configures new signal analyzer and stores it under given alias.
        :param model: model name of configured signal analyzer; supported models:
                        * KeysightN9935A
                        * KeysightN9020A
                        * KeysightN9040B
        :type model: str
        :param ip: IP address of signal analyzer to which connection will be established
        :type ip: str
        :param alias: name under which configured signal analyzer will be stored, i.e. my_signal_analyzer;
                      if already existing alias will be provided then no new signal analyzer will be set up
                      (already existing signal analyzer will be used);
                      defaults to None
        :type alias: str
        :param kwargs: additional signal analyzer parameters, i.e. port=5023, unlock_timeout=150
        :return: configured signal analyzer
        :rtype: SignalAnalyzer
        :raises IncorrectAlias: when given alias is invalid
        :raises UnsupportedSignalAnalyzer: when given signal analyzer model is not supported
        :raises DeviceLocked: if device won't become unlocked by other user before reaching timeout
        """
        logging.info("Setting up '{}' signal analyzer with alias '{}'".format(model, alias))

        try:
            device = self.configured_signal_analyzer.get(alias)
        except AliasLookupError:
            self._check_alias(alias)
            device = self._facade.setup_signal_analyzer(model, ip, **kwargs)
            self.configured_signal_analyzer.add(device, alias)

        return device

    @lookup_handler.implicit_lookup
    def set_mode(self, mode, timeout=20, alias=None):
        """
        Sets given operating mode on signal analyzer with given alias.
        :param mode: name of mode which will be set, i.e. SA
        :type mode: str
        :param timeout: time to wait for individual steps of this operation to be finished;
                        accepts Robot string time format i.e. 1 min 30 sec; defaults to 20 seconds
        :type timeout: int or str
        :param alias: name under which required signal analyzer is stored, i.e. my_signal_analyzer; defaults to None
        :type alias: str
        :raises AliasLookupError: when signal analyzer with given alias does not exist
        :raises IncorrectOperation: when unsupported mode is provided
        :raises UnsupportedOperation: when this operation is not supported by signal analyzer with given alias
        """
        logging.info("Setting mode '{}' on {}".format(mode, alias))
        self._facade.set_mode(alias, mode, time_to_seconds(timeout))

    @lookup_handler.implicit_lookup
    def get_mode(self, timeout=10, alias=None):
        """
        Gets current operating mode from signal analyzer with given alias.
        :param timeout: time to wait for individual steps of this operation to be finished;
                        accepts Robot string time format i.e. 1 min 30 sec; defaults to 10 seconds
        :type timeout: int or str
        :param alias: name under which required signal analyzer is stored, i.e. my_signal_analyzer; defaults to None
        :type alias: str
        :return: signal analyzer's current operating mode
        :rtype: str
        :raises AliasLookupError: when signal analyzer with given alias does not exist
        :raises UnsupportedOperation: when this operation is not supported by signal analyzer with given alias
        """
        logging.info("Getting mode from {}".format(alias))
        return self._facade.get_mode(alias, time_to_seconds(timeout))

